import java.util.*;

public class Main {
    static char[][] gridA = new char[20][20];
    static char[][] gridB = new char[20][20];
    static List<Edge> edges = new ArrayList<>();
    static int[] head;
    static int[] p;
    static int[] v;
    static int[] dep;
    static int[] next;
    static int[] u;
    static int[] flow;
    static int[] capacity;
    static int[] from;
    static int[] to;
    static int[] rev;
    static int cnt;
    static int s = 501;
    static int t = 502;
    static int totalFlow = 0;
    static int n, m;
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static final int INF = 1000000007;

    static class Edge {
        int u, v, flow, capacity, next;
        public Edge(int u, int v, int flow, int capacity, int next) {
            this.u = u;
            this.v = v;
            this.flow = flow;
            this.capacity = capacity;
            this.next = next;
        }
    }

    static void addEdge(int u, int v, int w) {
        edges.add(new Edge(u, v, 0, w, head[u]));
        head[u] = edges.size() - 1;
        edges.add(new Edge(v, u, 0, 0, head[v]));
        head[v] = edges.size() - 1;
    }

    static boolean bfs() {
        Arrays.fill(v, 0);
        Arrays.fill(dep, 0);
        Queue<Integer> q2 = new LinkedList<>();
        q2.offer(s);
        v[s] = 1;
        dep[s] = 1;
        while (!q2.isEmpty()) {
            int x = q2.poll();
            for (int i = head[x]; i != -1; i = edges.get(i).next) {
                Edge e = edges.get(i);
                if (v[e.v] == 0 && e.flow < e.capacity) {
                    p[e.v] = i;
                    q2.offer(e.v);
                    v[e.v] = 1;
                    dep[e.v] = dep[x] + 1;
                    if (e.v == t) return true;
                }
            }
        }
        return false;
    }

    static int dfs(int x, int flow) {
        if (x == t || flow == 0) return flow;
        int tFlow = flow;
        for (int i = head[x]; i != -1; i = edges.get(i).next) {
            Edge e = edges.get(i);
            if (e.capacity > e.flow && dep[e.v] == dep[x] + 1) {
                int delta = dfs(e.v, Math.min(tFlow, e.capacity - e.flow));
                if (delta == 0) dep[e.v] = 0;
                e.flow += delta;
                edges.get(p[e.v] ^ 1).flow -= delta;
                tFlow -= delta;
                if (tFlow == 0) break;
            }
        }
        return flow - tFlow;
    }

    static void executeDinic() {
        while (bfs()) {
            totalFlow += dfs(s, INF);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int tLimit = sc.nextInt();

        head = new int[505];
        Arrays.fill(head, -1);
        v = new int[505];
        p = new int[505];
        dep = new int[505];

        int[][] distA = new int[20][20];
        int[][][][] distB = new int[20][20][20][20];

        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 20; j++) {
                distA[i][j] = 10000;
            }
        }

        Queue<int[]> q = new LinkedList<>();

        for (int i = 1; i <= n; i++) {
            String line = sc.next();
            for (int j = 1; j <= n; j++) {
                gridA[i][j] - line.charAt(j - 1);
                if (gridA[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    distA[i][j] = 0;
                }
                if (gridA[i][j] <= '9') {
                    addEdge(s, (i - 1) * n + j, gridA[i][j] - '0');
                }
            }
        }

        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int x = cell[0], y = cell[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx > 0 && ny > 0 && nx <= n && ny <= n && gridA[nx][ny] <= '9' && distA[nx][ny] > distA[x][y] + 1) {
                    distA[nx][ny] = distA[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] > '9') continue;
                for (int k = 1; k <= n; k++) {
                    for (int l = 1; l <= n; l++) {
                        distB[i][j][k][l] = 10000;
                    }
                }
                q.offer(new int[]{i, j});
                distB[i][j][i][j] = 0;
                while (!q.isEmpty()) {
                    int[] cell2 = q.poll();
                    int x = cell2[0], y = cell2[1];
                    for (int f = 0; f < 4; f++) {
                        int nx = x + dx[f], ny = y + dy[f];
                        if (nx > 0 && ny > 0 && nx <= n && ny <= n && gridA[nx][ny] <= '9' && distB[i][j][nx][ny] > distB[i][j][x][y] + 1 && distA[x][y] < distA[nx][ny]) {
                            distB[i][j][nx][ny] = distB[i][j][x][y] + 1;
                            q.offer(new int[]{nx, ny});
                        }
                    }
                }
                for (int k = 1; k <= n; k++) {
                    for (int l = 1; l <= n; l++) {
                        if (distB[i][j][k][l] <= Math.min(distA[k][l], tLimit))
                            addEdge((i - 1) * n + j, (k - 1) * n + l + 100, 10000);
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            String line = sc.next();
            for (int j = 1; j <= n; j++) {
                gridB[i][j] = line.charAt(j - 1);
                if (gridB[i][j] <= '9') {
                    addEdge((i - 1) * n + j + 100, t, gridB[i][j] - '0');
                }
            }
        }

        executeDinic();
        System.out.println(totalFlow);
        sc.close();
    }
}
